function startQuiz(kind,questions,lesson=null,snapshot=null){quizReturn={tab,screen:screen==='quiz'?'main':screen};media.stop();if(!questions.length){toast('No practice questions are ready.');return;}if(kind!=='review')reviewFollowup='';if(lesson)viewStage=lesson.stage;quiz={kind,questions,lesson,index:0,answers:[],selected:null,checked:false,readingReady:false,modelRevealed:false,audioPlayed:false,audioUnavailable:false,audioLoading:false,listenRate,...(kind==='lesson'?{hintRevealed:false}:{}),spanishHelpRevealed:false,scaffoldRevealed:false,confidence:null,...(snapshot||{})};screen='quiz';persistQuiz();render();}
