function renderQuiz(){if(quiz.index>=quiz.questions.length){finishQuiz();return;}const tipEligible=quiz.kind==='lesson'&&quiz.lesson?.stage==='A1.1'&&quiz.lesson?.unit===0&&!quiz.lesson.reading&&!quiz.lesson.checkpoint&&state.dictionaryTipSeen!==true,showTip=tipEligible&&((state.dictionaryTipViews||0)<3||dictionaryTipLast===currentQuestion().id);if(showTip&&dictionaryTipLast!==currentQuestion().id){dictionaryTipLast=currentQuestion().id;state.dictionaryTipViews=Math.min(3,(state.dictionaryTipViews||0)+1);save();}app.innerHTML=(storageContext.readOnly?'<p class="notice" role="status">Temporary practice: your original save is protected. Export it from Profile before recovery; these attempts cannot be saved.</p>':'')+QuizView.render({quiz,E,b,esc,state,readingCard,lessonGoal,showDictionaryTip:showTip,compactMedia:currentQuestion()?.practice&&state.focused?.seenInstructions[currentQuestion().practice.kind]===true});refresh();}

function finishQuiz(){if(quiz.kind==='skill'){skillsResult=K.finish(state,quiz);E.markDay(state);save();screen='skillResult';app.innerHTML=header()+PracticeHub.result({quiz,round:skillsResult,b,esc,C});refresh();return;}if(quiz.kind==='focused'){focusedResult=F.finish(state,quiz);E.markDay(state);save();screen='focusedResult';app.innerHTML=header()+FocusedView.result({result:focusedResult,b,esc});refresh();return;}const scored=quiz.answers.filter((_,i)=>quiz.questions[i].type!=='speaking'&&!Writing.open(quiz.questions[i])),score=scored.filter(Boolean).length,total=scored.length;if(quiz.kind==='placement'){state.placement={answers:quiz.answers,stage:E.placementResult(quiz.answers),date:E.dayKey()};state.onboarded=true;screen='placementResult';quiz=null;save();render();return;}if(quiz.kind==='lesson'){E.complete(state,quiz.lesson,score,total,{reflected:Object.keys(quiz.writingResponses||{}).length});state.active=null;}else E.markDay(state);save();screen='main';const passed=total===0||score/total>=.8;app.innerHTML=header()+`<div class="card empty">${quiz.kind==='lesson'&&(quiz.lesson.checkpoint||!passed)?`<div class="lesson-bull ${passed?'happy':'sad'}" role="img" aria-label="${passed?'Happy bull celebrating your lesson':'Sad bull encouraging you to try again'}"></div>`:`<div class="icon">${passed?'🎉':'🌱'}</div>`}<h2>${passed?(quiz.kind==='lesson'?'Lesson complete 🎉':'Session complete'):'Keep building confidence'}</h2><p>${total?`${score} of ${total} correct`:'Reflection practice complete · self-assessed'}</p>${quiz.questions.some(q=>q.type==='speaking'||Writing.open(q))?'<p>Speaking and open-writing reflections are excluded from verified accuracy. Completing the task does not certify its grammar.</p>':''}<p>${quiz.kind==='lesson'&&!passed?'Reach 80% to complete this lesson. Your mistakes are ready for review.':'Every practice session helps your Spanish grow.'}</p>${reviewFollowup&&quiz.kind==='review'?b('Practise a weak conjugation','reviewFollowup','primary'):''}<details class="completion-more"><summary>More practice options</summary>${quiz.kind!=='placement'&&(quiz.kind!=='lesson'||passed)&&quiz.answers.some((a,i)=>a===false||a===null&&(quiz.questions[i].listening||quiz.writingResponses?.[i]?.reflection==='needs'))?b('Practise mistakes','practiseMistakes','pill'):''}${quiz.kind==='lesson'&&passed&&LearningQuality.concepts(quiz.questions[0],C).some(c=>state.completed.includes(c.source))?b('Practice this grammar','reinforceLesson','pill'):''}${quiz.kind==='review'||quiz.kind==='practice'?QualityView.summary(quiz,C,esc):''}</details>${quiz.lesson?'<p class="course-position">'+esc(X.position(quiz.lesson,C))+'</p><p>What you learned: '+esc(C.getUnit(quiz.lesson)?.goal||quiz.lesson.goal)+'.</p>':''}${todaySession?b(todaySession.steps.length?'Continue today’s session':'Finish today’s session','todayNext','primary'):quiz.kind==='lesson'?passed?completionNext()+b('Finish for now','home','pill'):b('Try again','retry','primary')+b('Review mistakes','lessonMistakes','pill')+b('Back to Home','home','pill'):quiz.microConcept?b('Continue practising','qualityMore','primary')+b('Return to Review','reviewHome','pill')+b('Back to Home','home','plain'):b('Back to Home','home','primary')}${quiz.kind==='lesson'&&!passed&&!todaySession?'':b('Try again','retry','pill')}</div>`;refresh();}
function completionNext(){const next=nextLesson(),kind=next?.checkpoint?'checkpoint':next?.reading?'story':next&&quiz.lesson&&next.unit!==quiz.lesson.unit||next&&quiz.lesson&&next.stage!==quiz.lesson.stage?'next unit':'next lesson';return `${next?'<section class="up-next"><span class="eyebrow">Up next · '+esc(next.stage)+'</span><h3>'+esc(AssessmentPolicy.title(next))+'</h3><p class="muted">'+(next.reading?'Short story':next.checkpoint?'Practical checkpoint':'Structured learning activity')+'</p></section>':'<p>Keep your skills fresh with due review or listening practice.</p>'}${b(next?'Continue to '+kind+' →':'Continue learning','continueLearning','primary')}`;}
