function startGame(mode='normal',mistakes=[]){if(state.games?.active&&mode!=='mistakes'&&!confirm('Replace your saved unfinished game?'))return;const attempt=G.build(state,C,mode,mistakes);if(!attempt){toast('No questions match this grammar level. Choose a level in Custom practice.');return;}state.games=state.games||G.empty();state.games.active=attempt;G.rememberShown(state);gameResult=null;quiz=null;todaySession=null;media.stop();screen='game';tab='Games';save();}
