 exportReports:()=>{const json=JSON.stringify({format:'friends-to-amigos-editorial-feedback-v1',reports:X.sanitizeReports(state.contentReports)},null,2);if(window.AndroidSpeech?.exportAnswerReports){AndroidSpeech.exportAnswerReports(json);return;}if(window.AndroidSpeech?.exportProgress){AndroidSpeech.exportProgress(json);return;}const url=URL.createObjectURL(new Blob([json],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='friends-to-amigos-answer-reports.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},
