 qualityPractice:el=>{const qs=LearningQuality.practice(state,C,el.dataset.id,el.dataset.key||'');if(qs.length)startQuiz('practice',qs,null,{microConcept:el.dataset.id,microFocus:el.dataset.key||''});else toast('Select the appropriate grammar level before practising this concept.');},
